-- ============================================================================
-- Real Estate Due Diligence Agent - 500 Synthetic Properties Dataset
-- Version: 1.0 (Phase 1 Database Import)
-- Generated according to JPA entity mappings and PostgreSQL database schema.
-- All records explicitly labeled as synthetic demonstration data.
-- Idempotent script: Safe to run multiple times without duplicating data.
-- ============================================================================

BEGIN;

-- Ensure master property types exist
INSERT INTO property_types (type_name, description, is_active, created_at, updated_at)
VALUES 
    ('Residential', 'Single and multi-family residential homes', true, NOW(), NOW()),
    ('Commercial', 'Commercial office, retail, and hospitality buildings', true, NOW(), NOW()),
    ('Industrial', 'Warehouses, manufacturing plants, and distribution centers', true, NOW(), NOW()),
    ('Mixed-Use', 'Properties combining commercial and residential spaces', true, NOW(), NOW())
ON CONFLICT (type_name) DO NOTHING;

-- Ensure master risk categories exist
INSERT INTO risk_categories (name, description, is_active, created_at, updated_at)
VALUES 
    ('Title & Ownership', 'Title defects, liens, encumbrances, ownership chain validation', true, NOW(), NOW()),
    ('Environmental', 'Phase I/II ESA, contamination, toxic substances, wetlands', true, NOW(), NOW()),
    ('Zoning & Land Use', 'Zoning compliance, setbacks, permitted uses, building codes', true, NOW(), NOW()),
    ('Flood & Climate', 'FEMA flood zone designation, sea-level rise, natural hazards', true, NOW(), NOW()),
    ('Structural & Physical', 'Foundation, MEP systems, roofing, seismic rating', true, NOW(), NOW()),
    ('Financial & Tax', 'Tax history, assessed value, NOI capitalization, loan-to-value', true, NOW(), NOW())
ON CONFLICT (name) DO NOTHING;

