INSERT INTO properties (property_code, property_type_id, property_name, title, description, built_year, total_area, land_area, market_value, status, created_by, created_at, updated_at)
SELECT 'SYN-RES-0001', pt.property_type_id, 'Highland Creek Estate #1', 'Highland Creek Estate #1', '[Demonstration Asset] Synthetic property record for due diligence simulation. Residential asset in Austin, TX featuring 1,273 sq ft.', 1981, 1273.00, 2800.60, 334500.00, 'AVAILABLE', COALESCE((SELECT user_id FROM users WHERE email = 'seller@demo.com' LIMIT 1), (SELECT user_id FROM users ORDER BY user_id LIMIT 1)), NOW() - INTERVAL '4 days', NOW()
FROM property_types pt WHERE pt.type_name = 'Residential' LIMIT 1
ON CONFLICT (property_code) DO NOTHING;
